/**
 * @file time-tracker.d.ts
 * @namespace TimeTracker
 * Единый файл с TypeScript-типами для всего модуля Time Tracker.
 * Содержит описания структур данных для справочника активностей (ранги, категории, типы)
 * и для расписаний (дневные планы, записи активностей), которые сохраняются в localStorage.
 * Файл разделён на логические блоки. Все типы экспортированы напрямую и готовы к использованию.
 */

// ============================================================================
// РАЗДЕЛ 1: СПРАВОЧНИК АКТИВНОСТЕЙ (Categories & Ranks)
// Используется для конфигурации иерархии задач и расчёта весов/ставок.
// ============================================================================

/**
 * Справочная формула (пояснение для пользователя, не используется в логике кода)
 */
export interface Formula {
  /** Название правила или ранга (например, "Делегируемые", "rate_base_rule") */
  name: string;
  /** Текстовое описание формулы с пояснениями */
  text: string;
}

/**
 * Метаданные и справочная информация файла конфигурации.
 * Эти данные носят описательный характер и не должны изменяться программно.
 */
export interface ServiceContext {
  /** Имя файла конфигурации */
  filename: string;
  /** Краткое описание назначения файла */
  description: string;
  /** Общая формула расчёта баланса дня */
  calculation_formula: string;
  /** Правила учёта времени и измерения активностей */
  measurement_rule: string;
  /** Массив поясняющих формул и правил расчёта весовых коэффициентов */
  formulas: Formula[];
}

/**
 * Ранг - корневой уровень иерархии активностей
 */
export interface Rank {
  /** Уникальный числовой идентификатор ранга, натуральное число */
  id: number;
  /** Название ранга на русском языке */
  name: string;
  /** Название ранга на английском языке (опционально) */
  name_en?: string;
  /** Подробное описание смысла и назначения ранга */
  description?: string;
  /** CSS-цвет для визуализации (именованный цвет или HEX-код) */
  color: string;
  /**
   * Весовой коэффициент для расчёта баланса (может быть отрицательным).
   * Должен быть целым числом, не равным нулю.
   */
  coefficient: number;
  /**
   * Денежная ставка в рублях за час (может быть отрицательной).
   * Должна быть целым числом, не равным нулю.
   */
  rate: number;
}

/**
 * Категория - группа активностей внутри ранга
 */
export interface Category {
  /** Уникальный числовой идентификатор категории, натуральное число */
  id: number;
  /** Внешний ключ, ссылается на поле `id` родительского ранга в массиве `ranks` */
  rank_id: number;
  /** Название категории */
  name: string;
  /** Подробное описание категории */
  description?: string;
  /** CSS-цвет для визуализации категории */
  color?: string;
}

/**
 * Тип активности - конкретное действие внутри категории
 */
export interface ActivityType {
  /** Уникальный числовой идентификатор типа активности, натуральное число */
  id: number;
  /** Внешний ключ, ссылается на поле `id` родительской категории в массиве `categories` */
  category_id: number;
  /** Название конкретной активности */
  name: string;
  /** Подробное описание типа активности */
  description?: string;
}

/**
 * Корневой объект файла конфигурации справочника
 */
export interface TimeTrackerData {
  /** Служебные метаданные и справочная информация о файле */
  _service_context: ServiceContext;
  /** Массив корневых уровней иерархии (рангов) */
  ranks: Rank[];
  /** Массив групп активностей внутри рангов */
  categories: Category[];
  /** Массив конкретных действий (типов активностей) внутри категорий */
  activity_types: ActivityType[];
}

// ============================================================================
// РАЗДЕЛ 2: РАСПИСАНИЯ (Schedules & Activity Entries)
// Используется для хранения дневных планов и фактических записей в localStorage.
// ============================================================================

/** Статус выполнения активности */
export type ActivityStatus = 'planned' | 'in_progress' | 'done';

/**
 * Запись активности – запланированное или выполненное дело в течение дня
 */
export interface ActivityEntry {
  /** Уникальный числовой идентификатор в пределах дня */
  id: number;
  /**
   * Идентификатор типа активности (activity_type.id)
   * из справочного файла конфигурации
   */
  activityTypeId: number;
  /** Время начала в минутах от полуночи, строго от 0 до 1439 включительно. Переход через полночь не допускается. */
  start: number;
  /** Время окончания в минутах от полуночи, строго от 1 до 1440 включительно (1440 = 24:00 следующего дня). Всегда больше start. */
  end: number;
  /** Общая длительность в минутах, всегда положительная: end - start (без перехода через полночь). */
  delta: number;
  /** Активное время в минутах (без учёта любых перерывов) */
  active: number;
  /** Прерывательные перерывы (в минутах) – из-за переключения на другую активность (явные переключения). */
  interruptBreaks: number;
  /** Неопределённые перерывы (в минутах) – отвлёкся непонятно на что, без чёткой привязки к другой задаче. */
  distractionBreaks: number;
  /** Комментарий пользователя (опционально) */
  comment?: string;
  /** Статус выполнения */
  status: ActivityStatus;
  /** Обязательное условие: delta === active + interruptBreaks + distractionBreaks */
}

/**
 * Расписание на один день
 */
export interface DaySchedule {
  /** Массив активностей дня */
  activities: ActivityEntry[];
}

/**
 * Элемент списка расписаний: дата + данные дня
 */
export interface ScheduleEntry {
  /**
   * Дата и время последнего обращения к расписанию (чтение или изменение).
   * Формат ISO 8601 с часовым поясом, например "2026-06-06T14:30:00+03:00".
   * Обновляется каждый раз, когда расписание дня загружается в интерфейс (например, при выборе даты в трекере) 
   * или при любом изменении активностей дня.
   */
  current_datetime: string;

  /** Дата в формате YYYY-MM-DD */
  date: string;
  /** Расписание на этот день */
  schedule: DaySchedule;
}

/**
 * Корневой объект, сохраняемый в localStorage по ключу `time-tracker-schedules`
 */
export interface SchedulesRoot {
  /** Дата и время последнего сохранения в формате ISO 8601 с часовым поясом, например "2026-06-06T14:30:00+03:00" */
  current_datetime: string;
  /** Массив расписаний по дням (порядок не гарантирован, для поиска используйте date) */
  schedules: ScheduleEntry[];
}